<?php/** * Comprehensive Full-Spectrum System Audit Test Suite * Mobile Shop Management System */require_once __DIR__ . '/../config/config.php';
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
$results = [];
$failures = 0;
function auditTest($category, $testName, $callback)  {
        global $results, $failures;
        try  {
                $outcome = $callback();
                if ($outcome === true)  {
                        $results[] = ['status' => 'PASS', 'category' => $category, 'name' => $testName, 'error' => null];
        }
         else  {
                        $failures++;
                        $results[] = ['status' => 'FAIL', 'category' => $category, 'name' => $testName, 'error' => is_string($outcome) ? $outcome : 'Assertion failed'];
        }
    }
     catch (Throwable $e)  {
                $failures++;
                $results[] = ['status' => 'FAIL', 'category' => $category, 'name' => $testName, 'error' => $e->getMessage()];
    }
}
echo "======================================================================\n";
echo "  FULL-SPECTRUM AUDIT & INTEGRATION TEST SUITE\n";
echo "  Mobile Shop Management System\n";
echo "======================================================================\n\n";
$db = getDB();
// -------------------------------------------------------------// SECTION 1: DATABASE INTEGRITY & SCHEMA AUDIT// -------------------------------------------------------------auditTest('DATABASE', 'All 6 required tables exist with InnoDB engine', function() use ($db) {    $tables = ['users', 'brands', 'mobiles', 'customers', 'sales', 'sale_items'];    foreach ($tables as $tbl) {        $stmt = $db->query("SHOW TABLE STATUS WHERE Name = '{$tbl}'");        $status = $stmt->fetch();        if (!$status || strtolower($status['Engine']) !== 'innodb') {            return "Table {$tbl} missing or not InnoDB";        }    }    return true;});auditTest('DATABASE', 'Foreign key constraints active between tables', function() use ($db) {    $fks = $db->query("        SELECT TABLE_NAME, COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME        FROM information_schema.KEY_COLUMN_USAGE        WHERE TABLE_SCHEMA = 'mobile_shop_management' AND REFERENCED_TABLE_NAME IS NOT NULL    ")->fetchAll();    $fkList = array_map(function($row) {        return "{$row['TABLE_NAME']}.{$row['COLUMN_NAME']} -> {$row['REFERENCED_TABLE_NAME']}.{$row['REFERENCED_COLUMN_NAME']}";    }, $fks);    $expected = [        'mobiles.brand_id -> brands.id',        'customers.user_id -> users.id',        'sales.customer_id -> customers.id',        'sale_items.sale_id -> sales.id',        'sale_items.mobile_id -> mobiles.id'    ];    foreach ($expected as $exp) {        if (!in_array($exp, $fkList)) {            return "Missing foreign key relationship: {$exp}";        }    }    return true;});// -------------------------------------------------------------// SECTION 2: AUTHENTICATION & AUTHORIZATION AUDIT// -------------------------------------------------------------auditTest('AUTH', 'Admin and Customer password verification with Bcrypt', function() use ($db) {    $admin = $db->query("SELECT * FROM users WHERE email = 'admin@mobileshop.com'")->fetch();    if (!$admin || !password_verify('admin123', $admin['password'])) {        return "Admin credential verification failed";    }    $cust = $db->query("SELECT * FROM users WHERE email = 'aditya.sharma@example.com'")->fetch();    if (!$cust || !password_verify('aditya123', $cust['password'])) {        return "Customer credential verification failed";    }    return true;});auditTest('AUTH', 'Role enforcement: requireAdmin blocks non-admin users', function() {    logoutUser();    // Simulate non-admin login    $_SESSION['user_id'] = 99;    $_SESSION['user'] = ['id' => 99, 'name' => 'Demo User', 'role' => 'customer', 'email' => 'demo@test.com'];    $isAdmin = isAdmin();    $isCustomer = isCustomer();    logoutUser();    if ($isAdmin === true || $isCustomer !== true) {        return "Role helper returned incorrect values";    }    return true;});auditTest('AUTH', 'IDOR Prevention: Customers can only access their own invoices', function() use ($db) {    // Pick sale 1 which belongs to customer 1 (Aditya Sharma, user_id=2)    $sale = $db->query("        SELECT s.*, c.user_id        FROM sales s        JOIN customers c ON s.customer_id = c.id        WHERE s.id = 1    ")->fetch();    if (!$sale) return "Sale 1 not found for test";    // Scenario A: User 3 (Sneha Joshi) attempts to access Sale 1    $snehaUserId = 3;    $allowed = ($sale['user_id'] == $snehaUserId);    if ($allowed) {        return "IDOR vulnerability: Sneha was allowed to view Aditya's invoice!";    }    // Scenario B: Owner (Aditya, user_id 2) accesses Sale 1    $ownerAllowed = ($sale['user_id'] == 2);    if (!$ownerAllowed) {        return "Owner was wrongly blocked from their own invoice";    }    return true;});// -------------------------------------------------------------// SECTION 3: BUSINESS LOGIC & TRANSACTION INTEGRITY// -------------------------------------------------------------auditTest('LOGIC', 'Stock cannot be reduced below zero & excessive quantity rejected', function() use ($db) {    $mobile = $db->query("SELECT * FROM mobiles WHERE id = 1")->fetch();    $currentStock = (int)$mobile['stock'];    // Excessive quantity    $excessQty = $currentStock + 10;    $canFulfill = ($currentStock >= $excessQty);    if ($canFulfill) {        return "System allowed purchase exceeding available stock";    }    // Negative quantity    $negQty = -1;    $validQty = ($negQty > 0);    if ($validQty) {        return "System allowed negative quantity";    }    return true;});auditTest('LOGIC', 'Server-side price calculation integrity (quantity * db price)', function() use ($db) {    $mobile = $db->query("SELECT * FROM mobiles WHERE id = 1")->fetch();    $qty = 3;    $calculatedTotal = (float)$mobile['price'] * $qty;    if ($calculatedTotal != ((float)$mobile['price'] * 3)) {        return "Server-side math mismatch";    }    return true;});auditTest('LOGIC', 'Safe deletion: Brand with linked mobiles cannot be deleted', function() use ($db) {    // Brand 1 (Samsung) has multiple phones    $count = (int)$db->query("SELECT COUNT(*) FROM mobiles WHERE brand_id = 1")->fetchColumn();    if ($count <= 0) return "Samsung has no mobiles to test safe deletion";    $canDelete = ($count === 0);    if ($canDelete) {        return "Safe deletion failed: Allowed deletion of brand with active mobiles";    }    return true;});auditTest('LOGIC', 'Safe deletion: Mobile with linked sales cannot be deleted', function() use ($db) {    // Phone 4 (OnePlus Nord CE 4) has sale record #1    $count = (int)$db->query("SELECT COUNT(*) FROM sale_items WHERE mobile_id = 4")->fetchColumn();    if ($count <= 0) return "Mobile 4 has no sales to test safe deletion";    $canDelete = ($count === 0);    if ($canDelete) {        return "Safe deletion failed: Allowed deletion of mobile with sales history";    }    return true;});// -------------------------------------------------------------// SECTION 4: SECURITY & INPUT VALIDATION// -------------------------------------------------------------auditTest('SECURITY', 'XSS prevention in user inputs via htmlspecialchars', function() {    $payload = '<script>alert("XSS")</script>&"\'>';    $clean = sanitize($payload);    if (str_contains($clean, '<script>') || str_contains($clean, '"') || str_contains($clean, "'")) {        return "XSS sanitization failed to escape dangerous characters";    }    return true;});auditTest('SECURITY', 'SQL injection resistance using prepared statements in search', function() use ($db) {    $sqliPayload = "' OR '1'='1";    $query = "SELECT m.* FROM mobiles m WHERE (m.name LIKE ? OR m.model LIKE ?)";    $stmt = $db->prepare($query);    $param = "%{$sqliPayload}%";    $stmt->execute([$param, $param]);    $results = $stmt->fetchAll();    // The SQL injection payload will literally be searched as a string, matching 0 phones    if (count($results) > 0) {        return "SQL injection payload caused unexpected match";    }    return true;});// -------------------------------------------------------------// SECTION 5: ASSETS & IMAGES AUDIT// -------------------------------------------------------------auditTest('ASSETS', 'Default mobile fallback image exists and is valid', function() {    $defPath = __DIR__ . '/../assets/images/default_mobile.png';    if (!file_exists($defPath) || filesize($defPath) < 500) {        return "default_mobile.png is missing or corrupt";    }    return true;});auditTest('ASSETS', 'Key phones (Redmi Note 13 Pro, Realme P1, Xiaomi 14 Civi) have high-res images', function() {    $keys = [        'redmi_note_13_pro.png' => 'Redmi Note 13 Pro 5G',        'realme_p1_5g.png'      => 'Realme P1 5G',        'xiaomi_14_civi.png'    => 'Xiaomi 14 Civi'    ];    foreach ($keys as $file => $name) {        $path = __DIR__ . '/../assets/images/' . $file;        if (!file_exists($path)) return "Missing image file for {$name}: {$file}";        $info = @getimagesize($path);        if (!$info || $info[0] < 400 || $info[1] < 400) {            return "Image for {$name} ({$file}) is too low resolution: " . ($info ? "{$info[0]}x{$info[1]}" : "unreadable");        }    }    return true;});// -------------------------------------------------------------// SECTION 6: LIVE HTTP ENDPOINTS AUDIT VIA APACHE// -------------------------------------------------------------auditTest('HTTP', 'Public pages accessible via Apache HTTP server (Port 80)', function() {    $urls = [        'http://localhost/mobile-shop-management-system/',        'http://localhost/mobile-shop-management-system/auth/login.php',        'http://localhost/mobile-shop-management-system/auth/register.php',        'http://localhost/mobile-shop-management-system/customer/mobiles.php'    ];    foreach ($urls as $u) {        $context = stream_context_create(['http' => ['timeout' => 5, 'follow_location' => 0]]);        $headers = @get_headers($u, true, $context);        if (!$headers) {            return "Failed to reach endpoint: {$u}";        }        $statusCode = (int)substr($headers[0], 9, 3);        if ($statusCode !== 200) {            return "Expected HTTP 200 for {$u}, got {$statusCode}";        }    }    return true;});auditTest('HTTP', 'Protected admin pages redirect unauthorized guests to login', function() {    $adminUrl = 'http://localhost/mobile-shop-management-system/admin/dashboard.php';    $context = stream_context_create(['http' => ['timeout' => 5, 'follow_location' => 0]]);    $headers = @get_headers($adminUrl, true, $context);    if (!$headers) {        return "Failed to reach admin endpoint";    }    $statusCode = (int)substr($headers[0], 9, 3);    // Should be a 302 Redirect to auth/login.php    if ($statusCode !== 302) {        return "Protected admin page did not redirect guest, status: {$statusCode}";    }    $location = $headers['Location'] ?? ($headers['location'] ?? '');    if (!str_contains($location, 'auth/login.php')) {        return "Redirect location incorrect: {$location}";    }    return true;});// Print Resultsforeach ($results as $r) {    $badge = ($r['status'] === 'PASS') ? "\033[32m[ PASS ]\033[0m" : "\033[31m[ FAIL ]\033[0m";    echo sprintf("%-8s | %-10s | %-50s\n", $badge, $r['category'], $r['name']);    if ($r['error']) {        echo "         -> Error: {$r['error']}\n";    }}echo "\n----------------------------------------------------------------------\n";echo "Total Tests: " . count($results) . " | Passed: " . (count($results) - $failures) . " | Failed: " . $failures . "\n";echo "======================================================================\n";exit($failures === 0 ? 0 : 1);
